  1	package hotel.reservations;
  2	
  3	import hotel.rooms.Room;
  4	import java.math.BigDecimal;
  5	import java.math.RoundingMode;
  6	import java.time.LocalDate;
  7	import java.time.Month;
  8	
  9	/**
 10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 12	 * (half-even) at every step.
 13	 */
 14	public final class PriceCalculator {
 15	
 16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 18	
 19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 20	        int nights = 0;
 21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 23	            subtotal = subtotal.add(nightPrice(room, night));
 24	            nights++;
 25	        }
 26	        BigDecimal discount = switch (ratePlan) {
 27	            case STANDARD -> cents(BigDecimal.ZERO);
 28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 29	        };
 30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 31	    }
 32	
 33	    BigDecimal nightPrice(Room room, LocalDate night) {
 34	        BigDecimal nightlyRate = room.nightlyRate();
 35	        if (isHighSeason(night)) {
 36	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 37	        }
 38	        return cents(nightlyRate);
 39	    }
 40	
 41	    /** High season: from December 15 to the end of February, and the whole of July. */
 42	    static boolean isHighSeason(LocalDate date) {
 43	        Month month = date.getMonth();
 44	        return month == Month.JANUARY
 45	                || month == Month.FEBRUARY
 46	                || month == Month.JULY
 47	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
 48	    }
 49	
 50	    static BigDecimal cents(BigDecimal value) {
 51	        return value.setScale(2, RoundingMode.HALF_EVEN);
 52	    }
 53	}
 54	package hotel.reservations;
 55	
 56	import hotel.documents.ReservationReceipt;
 57	import hotel.messages.EmailSender;
 58	import hotel.rooms.Room;
 59	import hotel.rooms.Rooms;
 60	import java.math.BigDecimal;
 61	
 62	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 63	public final class ReservationService {
 64	
 65	    static final String HOTEL_NAME = "Pousada Maré Alta";
 66	
 67	    private final Rooms rooms;
 68	    private final ReservationStore store;
 69	    private final PriceCalculator priceCalculator;
 70	    private final EmailSender emailSender;
 71	
 72	    public ReservationService(
 73	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 74	        this.rooms = rooms;
 75	        this.store = store;
 76	        this.priceCalculator = priceCalculator;
 77	        this.emailSender = emailSender;
 78	    }
 79	
 80	    public synchronized Reservation create(NewReservation request) {
 81	        if (!request.checkOut().isAfter(request.checkIn())) {
 82	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 83	        }
 84	        if (request.guests() < 1) {
 85	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 86	        }
 87	        Room room = rooms.find(request.roomNumber())
 88	                .orElseThrow(() -> new HotelException(
 89	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 90	        if (request.guests() > room.capacity()) {
 91	            throw new HotelException(
 92	                    ErrorCode.CAPACITY_EXCEEDED,
 93	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 94	        }
 95	        boolean roomTaken = store.all().stream()
 96	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
 97	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
 98	        if (roomTaken) {
 99	            throw new HotelException(
100	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
101	        }
102	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
103	        Reservation reservation = new Reservation(store.nextId(), request, price);
104	        store.save(reservation);
105	        return reservation;
106	    }
107	
108	    public Reservation find(long reservationId) {
109	        return store.find(reservationId)
110	                .orElseThrow(() -> new HotelException(
111	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
112	    }
113	
114	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
115	    public synchronized Reservation confirm(long reservationId) {
116	        Reservation reservation = find(reservationId);
117	        if (reservation.status() != ReservationStatus.PENDING) {
118	            throw notAllowed(reservation, "confirm");
119	        }
120	        reservation.confirmPayment();
121	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
122	        emailSender.send(
123	                reservation.guest().email(),
124	                "Reserva confirmada - " + HOTEL_NAME,
125	                confirmationEmailBody(reservation, receipt));
126	        return reservation;
127	    }
128	
129	    /**
130	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
131	     * reservation was never paid, so nothing comes back).
132	     */
133	    public synchronized Reservation cancel(long reservationId) {
134	        Reservation reservation = find(reservationId);
135	        if (reservation.status() != ReservationStatus.PENDING
136	                && reservation.status() != ReservationStatus.CONFIRMED) {
137	            throw notAllowed(reservation, "cancel");
138	        }
139	        BigDecimal refund = switch (reservation.ratePlan()) {
140	            case STANDARD -> reservation.amountPaid();
141	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
142	        };
143	        reservation.cancel(refund);
144	        return reservation;
145	    }
146	
147	    public synchronized Reservation checkIn(long reservationId) {
148	        Reservation reservation = find(reservationId);
149	        if (reservation.status() != ReservationStatus.CONFIRMED) {
150	            throw notAllowed(reservation, "check in");
151	        }
152	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
153	        return reservation;
154	    }
155	
156	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
157	    public synchronized ReservationReceipt checkOut(long reservationId) {
158	        Reservation reservation = find(reservationId);
159	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
160	            throw notAllowed(reservation, "check out");
161	        }
162	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
163	        return new ReservationReceipt(reservation, roomOf(reservation));
164	    }
165	
166	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
167	    public ReservationReceipt receiptCopy(long reservationId) {
168	        Reservation reservation = find(reservationId);
169	        if (!reservation.isPaid()) {
170	            throw notAllowed(reservation, "issue a receipt for");
171	        }
172	        return new ReservationReceipt(reservation, roomOf(reservation));
173	    }
174	
175	    private Room roomOf(Reservation reservation) {
176	        return rooms.find(reservation.roomNumber()).orElseThrow();
177	    }
178	
179	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
180	        return "Olá, " + reservation.guest().name() + "!\n\n"
181	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
182	                + receipt.text() + "\n"
183	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
184	                + "Até breve!\n";
185	    }
186	
187	    private static HotelException notAllowed(Reservation reservation, String operation) {
188	        return new HotelException(
189	                ErrorCode.OPERATION_NOT_ALLOWED,
190	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
191	    }
192	}
