194	
195	public enum RatePlan {
196	    /** Full price; the guest gets everything back when cancelling a confirmed reservation. */
197	    STANDARD,
198	    /** 15% off, but nothing comes back on cancellation. */
199	    NON_REFUNDABLE
200	}

